 "content": "from collections import Counter


def transform(grid):
    """Reduce a grid to 3x3-cell tiles, taking the most common non-5 color."""
    out = []
    for r in range(0, len(grid), 3):
        row = []
        for c in range(0, len(grid[0]), 3):
            counts = Counter(
                grid[i][j]
                for i in range(r, min(r + 3, len(grid)))
                for j in range(c, min(c + 3, len(grid[0])))
                if grid[i][j] != 5
            )
            row.append(counts.most_common(1)[0][0] if counts else 5)
        out.append(row)
    return out
